/* =========================================================================
   IMPRESSÃO 3D — orçamento, produção e custos
   -------------------------------------------------------------------------
   Módulo nativo, integrado ao JeV Empreendimentos: usa as mesmas tabelas
   (financeiro, pessoas) onde faz sentido e tabelas próprias só para o que é
   específico de impressão 3D (impressoras3d, filamentos, movfilamento,
   orcamentos3d, produtos3d, producoes3d — ver STORES em 03_core.js).

   Identidade visual: este módulo usa a marca "J&V Artigos 3D" (a logo
   embutida em IMP3D_LOGO, acima) nos cartões e cabeçalhos de suas próprias
   telas — o resto do sistema continua com a identidade JeV normalmente.
   A cor de contexto do módulo (--uc / --ucb) vem da UNIDADE 'imp3d' em
   04_dados.js.

   Esta primeira versão entrega a fundação: navegação, banco de dados e o
   esqueleto das 11 telas. Cada tela é completada numa etapa seguinte,
   testada antes de avançar — conforme combinado.
   ========================================================================= */


function imp3dCabecalho(titulo, subtitulo){
  const U = unInfo('imp3d');
  return `<div class="ph">
    <div class="ico" style="width:46px;height:46px;border-radius:12px;overflow:hidden;flex:none;
      display:flex;align-items:center;justify-content:center;background:${U.bg}">
      <img src="${IMP3D_LOGO}" alt="J&amp;V Artigos 3D" style="width:100%;height:100%;object-fit:cover">
    </div>
    <div><h1>${esc(titulo)}</h1><p>${esc(subtitulo)}</p></div></div>`;
}

function imp3dEmConstrucao(raizId, titulo, subtitulo){
  document.getElementById(raizId).innerHTML = imp3dCabecalho(titulo, subtitulo) +
    `<div class="al ai"><i class="ti ti-tool"></i>Esta tela ainda está sendo construída — chega numa próxima etapa.</div>`;
}

