/* ---------------------------------------------------------------- Serviço de cálculo
   Motor de formação de preço da Impressão 3D — função pura, sem tocar o banco
   nem a tela, para poder ser testada isoladamente (ver test_imp3d_calc.js).
   Segue as fórmulas A–K definidas na especificação do módulo; cada bloco do
   código cita a letra correspondente. Nunca lê os números já formatados na
   tela como entrada — trabalha só com os valores numéricos recebidos. */
function imp3dCalcular(p){
  const g = (v)=> isNaN(parseFloat(v)) ? 0 : parseFloat(v); // num() local, sem depender do DOM
  const avisos = [];

  // --------- A. Custo de material (peso consumido × custo por grama do filamento)
  const custoMaterial = g(p.pesoConsumidoG) * g(p.custoPorGramaMaterial);

  // --------- B. Custo de energia
  const custoEnergia = (g(p.potenciaW)/1000) * g(p.tempoHoras) * g(p.tarifaKwh);

  // --------- C. Depreciação da impressora (custo de depreciação/h já calculado por
  // imp3dDeprecInfo, a partir do cadastro da impressora) × tempo de impressão
  const custoDeprec = g(p.custoDeprecHora) * g(p.tempoHoras);

  // --------- D. Manutenção — por hora OU fixa por peça, nunca as duas (evita cobrar em dobro)
  const manutModo = p.manutModo === 'fixo' ? 'fixo' : 'hora';
  const custoManut = manutModo==='fixo' ? g(p.custoManutFixoPeca) : g(p.custoManutHora) * g(p.tempoHoras);

  // --------- E. Mão de obra (soma dos tempos manuais aplicáveis × valor da hora)
  const horasManuais = g(p.tempoPreparoH)+g(p.tempoRemocaoH)+g(p.tempoAcabamentoH)+g(p.tempoMontagemH)+g(p.tempoEmbalagemH);
  const custoMaoObra = horasManuais * g(p.valorHoraTrabalho);

  // --------- F. Outros custos diretos — materiais adicionais, desperdício não incluído no
  // peso consumido, suportes/ferragens, embalagem e demais custos diretos aplicáveis.
  // (o peso consumido informado já deve trazer suportes/purga/brim do fatiador — este
  // "desperdício adicional" é só o que NÃO estiver incluído nesse peso, para não contar
  // a mesma perda duas vezes)
  const custoDesperdicioAdicional = g(p.desperdicioAdicionalG) * g(p.custoPorGramaMaterial);
  const outrosCustosDiretos = g(p.materiaisAdicionais) + custoDesperdicioAdicional + g(p.custoSuportesFerragens) +
                              g(p.embalagem) + g(p.custosAdicionaisDiretos);

  // --------- G. Custo-base de produção
  const custoBase = custoMaterial + custoEnergia + custoDeprec + custoManut + custoMaoObra + outrosCustosDiretos;

  // --------- H. Reserva para falhas — aproximação de orçamento, não garantia de cobertura total
  const reservaFalhasPct = g(p.reservaFalhasPct);
  const reservaFalhas = custoBase * reservaFalhasPct/100;

  // --------- I. Custo de produção ajustado
  const custoAjustado = custoBase + reservaFalhas;

  // percentuais cobrados sobre o preço de venda (receita), não sobre o custo
  const taxasVendaPct = g(p.taxasPagamentoPct) + g(p.comissaoMarketplacePct) + g(p.impostosVendaPct);

  const modoPreco = p.modoPreco === 'margem' ? 'margem' : 'markup';
  let precoVendaUnitario = null;
  let precoAntesTaxas = null;

  if(modoPreco==='markup'){
    // --------- J. Preço com markup — resultado é o preço ANTES das taxas sobre a venda
    precoAntesTaxas = custoAjustado * (1 + g(p.markupPct)/100);
    if(taxasVendaPct > 0){
      // há comissão/taxa/imposto percentual sobre a venda: não basta somar um percentual
      // sobre o CUSTO — a cobrança é sobre a RECEITA, então o preço precisa ser "regrossado"
      // para que, depois de pagas essas taxas, o markup pedido ainda sobre intacto.
      if(taxasVendaPct >= 100){
        avisos.push('A soma das taxas sobre a venda (pagamento + comissão + impostos) é igual ou maior que 100% — não é possível calcular um preço válido com essas taxas.');
        precoVendaUnitario = null;
      } else {
        precoVendaUnitario = precoAntesTaxas / (1 - taxasVendaPct/100);
      }
    } else {
      precoVendaUnitario = precoAntesTaxas;
    }
  } else {
    // --------- K. Preço com margem sobre a receita
    const margemPct = g(p.margemDesejadaPct);
    const somaPct = margemPct + taxasVendaPct;
    const custosFixosPorUnidade = custoAjustado + g(p.custosFixosAdicionaisVenda);
    if(somaPct >= 100){
      avisos.push('A soma da margem desejada com as taxas percentuais sobre a venda é igual ou maior que 100% — não é possível calcular um preço válido com essa margem.');
      precoVendaUnitario = null;
    } else {
      precoVendaUnitario = custosFixosPorUnidade / (1 - somaPct/100);
    }
  }

  // desconto comercial — aplicado sobre o preço já calculado, depois de tudo
  let precoFinalUnitario = precoVendaUnitario;
  if(precoFinalUnitario != null && g(p.descontoComercial) > 0){
    precoFinalUnitario = p.descontoComercialModo === 'percentual'
      ? precoFinalUnitario * (1 - g(p.descontoComercial)/100)
      : Math.max(0, precoFinalUnitario - g(p.descontoComercial));
  }

  const quantidade = g(p.quantidade) || 1;
  const lucroUnitario = precoFinalUnitario!=null ? precoFinalUnitario - custoAjustado : null;
  const margemEstimadaPct = (precoFinalUnitario && precoFinalUnitario>0) ? (lucroUnitario/precoFinalUnitario*100) : null;

  return {
    custoMaterial, custoEnergia, custoDeprec, custoManut, custoMaoObra, outrosCustosDiretos,
    custoBase, reservaFalhas, custoAjustado,
    modoPreco, precoAntesTaxas, taxasVendaPct, precoVendaUnitario, precoFinalUnitario,
    quantidade, custoTotalLote: custoAjustado*quantidade,
    valorTotalOrcamento: precoFinalUnitario!=null ? precoFinalUnitario*quantidade : null,
    lucroUnitario, resultadoLote: lucroUnitario!=null ? lucroUnitario*quantidade : null,
    margemEstimadaPct,
    tempoTotalMaquinaH: g(p.tempoHoras) * quantidade,
    materialTotalG: g(p.pesoConsumidoG) * quantidade,
    avisos
  };
}
/* arredonda só na APRESENTAÇÃO — nunca usar o valor arredondado como entrada de outro cálculo */
function imp3dMoedaCalc(v){ return v==null ? '—' : moeda(v); }

/* ---------------------------------------------------------------- Impressoras 3D
   Depreciação por hora = (valor de compra - valor residual) / vida útil em horas
   (usa a vida útil revisada quando informada). Nunca divide por zero: sem vida
   útil válida, a depreciação fica indefinida (null) e a tela avisa, em vez de
   mostrar um número inventado. */
function imp3dDeprecInfo(imp){
  const compra = num(imp.valorCompra);
  const residual = num(imp.valorResidual);
  const vidaUtil = num(imp.vidaUtilRevisada) > 0 ? num(imp.vidaUtilRevisada) : num(imp.vidaUtilHoras);
  const depreciavel = Math.max(0, compra - residual);
  if(vidaUtil <= 0) return { valida:false, custoHora:null, depreciavel, vidaUtil };
  return { valida:true, custoHora: depreciavel / vidaUtil, depreciavel, vidaUtil };
}
/* custo de manutenção considerado na formação de preço: por hora OU fixo por
   peça — nunca os dois juntos, para não cobrar a manutenção em dobro (ver 8.2-D) */
function imp3dManutInfo(imp){
  const modo = imp.manutModo === 'fixo' ? 'fixo' : 'hora';
  return modo==='fixo'
    ? { modo, custoHora:0, custoFixoPeca: num(imp.manutFixoPeca) }
    : { modo, custoHora: num(imp.manutPorHora), custoFixoPeca: 0 };
}

let IMP3D_IMP_TAB = 'ativas';
async function imp3dImpRender(){
  const root = document.getElementById('i3imp-root');
  const todas = await dbGetAll('impressoras3d');
  const ativas = todas.filter(i=>i.status!=='Inativa');
  const valorFrota = todas.reduce((s,i)=>s+num(i.valorCompra),0);
  const comDeprec = ativas.map(i=>imp3dDeprecInfo(i)).filter(d=>d.valida);
  const deprecMedia = comDeprec.length ? comDeprec.reduce((s,d)=>s+d.custoHora,0)/comDeprec.length : 0;
  const semVidaUtil = ativas.filter(i=>!imp3dDeprecInfo(i).valida);

  let h = imp3dCabecalho('Impressoras 3D', 'Equipamentos, depreciação e custo por hora');

  h += `<div class="kg" style="margin-bottom:16px">
    <div class="kc br"><div class="lb"><i class="ti ti-printer"></i>Impressoras</div>
      <div class="vl">${todas.length}</div><div class="sb">${ativas.length} ativa(s)</div></div>
    <div class="kc gd"><div class="lb"><i class="ti ti-currency-real"></i>Valor investido</div>
      <div class="vl">${moedaK(valorFrota)}</div><div class="sb">soma do valor de compra</div></div>
    <div class="kc gn"><div class="lb"><i class="ti ti-trending-down"></i>Depreciação média/h</div>
      <div class="vl">${comDeprec.length?moeda(deprecMedia):'—'}</div><div class="sb">entre as impressoras ativas</div></div>
    <div class="kc ${semVidaUtil.length?'am':'tl'}"><div class="lb"><i class="ti ti-alert-triangle"></i>Sem vida útil informada</div>
      <div class="vl">${semVidaUtil.length}</div><div class="sb">não entram no cálculo de depreciação</div></div>
  </div>`;

  h += `<div class="brow" style="margin-bottom:12px">
    <button class="btn gh ${IMP3D_IMP_TAB==='ativas'?'on':''}" onclick="IMP3D_IMP_TAB='ativas';imp3dImpRender()">Ativas e em manutenção</button>
    <button class="btn gh ${IMP3D_IMP_TAB==='todas'?'on':''}" onclick="IMP3D_IMP_TAB='todas';imp3dImpRender()">Todas</button>
    <div class="sp"></div>
    <button class="btn" style="background:#16253B" onclick="imp3dImpForm()"><i class="ti ti-plus"></i>Nova impressora</button>
  </div>`;

  const lista = IMP3D_IMP_TAB==='ativas' ? todas.filter(i=>i.status!=='Inativa') : todas;

  if(!todas.length){
    h += `<div class="card"><div class="bd"><div class="empty"><i class="ti ti-printer"></i>
      <b>Nenhuma impressora cadastrada</b>Cadastre suas impressoras para calcular depreciação, custo por hora
      e usar na calculadora de preços.
      <div class="brow" style="justify-content:center;margin-top:14px">
      <button class="btn" style="background:#16253B" onclick="imp3dImpForm()"><i class="ti ti-plus"></i>Cadastrar impressora</button></div></div></div></div>`;
  } else if(!lista.length){
    h += `<div class="al ai"><i class="ti ti-info-circle"></i>Nenhuma impressora ${IMP3D_IMP_TAB==='ativas'?'ativa':''} nesse filtro.</div>`;
  } else {
    h += `<div class="mgrid">`;
    lista.forEach(i=>{
      const d = imp3dDeprecInfo(i);
      h += `<div class="ocard" onclick="imp3dImpForm(${i.id})">
        <div class="oh"><div class="oi" style="background:#E7EBF0;color:#16253B"><i class="ti ti-printer"></i></div>
          <div style="flex:1;min-width:0"><b style="display:block;font-size:13.5px">${esc(i.nome)}</b>
            <span class="tt">${esc(i.fabricante||'')} ${esc(i.modelo||'')}</span></div>
          <span class="st ${ST_IMPRESSORA3D[i.status]||'s-nt'}">${esc(i.status||'Ativa')}</span></div>
        <div class="ob">
          <div class="row"><span>Tecnologia</span><b>${esc(i.tecnologia||'—')}</b></div>
          <div class="row"><span>Valor de compra</span><b>${moeda(i.valorCompra)}</b></div>
          <div class="row"><span>Depreciação/h</span><b>${d.valida?moeda(d.custoHora):'—'}</b></div>
          <div class="row"><span>Potência média</span><b>${i.potenciaW?num(i.potenciaW)+' W':'—'}</b></div>
        </div></div>`;
    });
    h += `</div>`;
  }

  root.innerHTML = h;
}

