async function imp3dProdRender(){ imp3dEmConstrucao('i3prod-root', 'Produtos e projetos', 'Catálogo de peças e projetos impressos'); }
async function imp3dHistRender(){ imp3dEmConstrucao('i3hist-root', 'Histórico de produção', 'Impressões em andamento e concluídas'); }
async function imp3dRelRender(){ imp3dEmConstrucao('i3rel-root', 'Relatórios financeiros', 'Faturamento, custos e resultado da unidade'); }
async function imp3dCfgRender(){ imp3dEmConstrucao('i3cfg-root', 'Configurações de cálculo', 'Percentual padrão de falhas e demais parâmetros'); }
